class Folder implements Component {
  children: Component[] = []
  addChild(c: Component) { this.children.push(c) }
  render() { return this.children.map(c => c.render()).join('\n') }
}

// client code
function attach(parent: Component, child: Component) {
  if (parent instanceof Folder) parent.addChild(child)
}

