interface Component { render(): string }
interface Container { add(c: Component): void; remove(c: Component): void }
class Folder implements Component, Container { private children: Component[] = []
  add(c: Component) { this.children.push(c) }
  remove(c: Component) { this.children = this.children.filter(x => x !== c) }
  render() { return this.children.map(c => c.render()).join(',') }
}
class File implements Component { render() { return 'file' } }

// Version B
interface ComponentV2 { render(): string; add?(c: ComponentV2): void }
class FolderV2 implements ComponentV2 { children: ComponentV2[] = []; add(c: ComponentV2) { this.children.push(c) } render() { return '' } }
class FileV2 implements ComponentV2 { render() { return 'file' } add(c: ComponentV2) { throw new Error('cannot add to leaf') } }
